// BenchmarkMACSuite measures each callable of the suite of MAC on macIdle.
func BenchmarkMACSuite(b *testing.B) {
	b.Run("ID", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.ID.Callable, macIdle)
	})
	b.Run("Algorithm", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.Algorithm.Callable, macIdle)
	})
	b.Run("Size", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.Size.Callable, macIdle)
	})
	b.Run("Sign", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.Sign.Callable, macIdle)
	})
	b.Run("Verify", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.Verify.Callable, macIdle)
	})
	b.Run("NewStream", func(b *testing.B) {
		cryptotest.BenchMACSuite(b, cryptotest.MACChecks.NewStream.Callable, macIdle)
	})
}

// BenchmarkMACSuiteParallel measures each callable of the suite of MAC
// that admits concurrent calls on macIdle, on GOMAXPROCS goroutines at
// once.
func BenchmarkMACSuiteParallel(b *testing.B) {
	b.Run("Sign", func(b *testing.B) {
		cryptotest.BenchMACSuiteParallel(b, cryptotest.MACChecks.Sign.Callable, macIdle)
	})
}

